const digest = $json.data;
const cfg = $('Configure Telegram Destinations').first().json;
const destinations = JSON.parse(cfg.destinationsJson || '[]');
const lines = digest.categories.map((row) => `${row.label}: ${row.actualVp} VP (target ${row.targetVp})`);
const changeLine = digest.changeCount === 0 ? 'No changes since the previous digest.' : `${digest.changeCount} updated entr${digest.changeCount === 1 ? 'y' : 'ies'} since the previous digest.`;
const text = [`UHP Volume Points - ${digest.reportingMonth.slice(0, 7)}`, ...lines, `Total: ${digest.totalActualVp} VP`, changeLine].join('\n');
return destinations.map((destination) => ({ json: { ...digest, controlHubUrl: cfg.controlHubUrl, destinationKey: destination.key, chatId: destination.chatId, telegramText: text, idempotencyKey: `vp-digest:${digest.intervalEndedAt.slice(0, 10)}:${destination.key}` } }));
